//! Reader trust files under `<configRoot>/seal/` and `loam seal trust`.
//!
//! The directory holds, and only ever holds locally (never committed):
//!
//! - `agent_ed25519` / `agent_ed25519.pub`: this instance's signing key,
//!   generated by `ssh-keygen` itself (never copied; Windows refuses loose
//!   ACLs on private keys).
//! - `instance`: the one-line instance id, written once and read thereafter.
//! - `allowed_signers`: ssh-keygen format, every option value quoted. Lines
//!   are never deleted; a validity window is closed instead.
//! - `revoked`: public keys that no signature may verify against.
//! - `policy.json` (`loam.seal-policy/v1`): reader policy, defaults when absent.

use crate::json::{self, Value};
use crate::seal::sshsig;
use crate::seal::{EXIT_OK, EXIT_REFUSED, EXIT_USAGE};
use crate::sha256;
use std::fmt;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::Command;

pub const KEY_FILE: &str = "agent_ed25519";
pub const PUBLIC_FILE: &str = "agent_ed25519.pub";
pub const INSTANCE_FILE: &str = "instance";
pub const ALLOWED_FILE: &str = "allowed_signers";
pub const REVOKED_FILE: &str = "revoked";
pub const POLICY_FILE: &str = "policy.json";
pub const POLICY_TYPE: &str = "loam.seal-policy/v1";
pub const DEFAULT_MAX_REVIEW: &str = "180d";
pub const DEFAULT_CAPTURE_MAX_BYTES: u64 = 262_144;
pub const DEFAULT_ENFORCEMENT: &str = "warn";
const DEFAULT_AUDITED_PRINCIPALS: &str = "agent.*@*";

/// A trust-file problem. `line` is 1-based, 0 when not tied to a line.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TrustError {
    pub file: &'static str,
    pub line: usize,
    pub message: String,
}

impl fmt::Display for TrustError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.line > 0 {
            write!(f, "{} line {}: {}", self.file, self.line, self.message)
        } else {
            write!(f, "{}: {}", self.file, self.message)
        }
    }
}

fn err(file: &'static str, line: usize, message: impl Into<String>) -> TrustError {
    TrustError {
        file,
        line,
        message: message.into(),
    }
}

/// One `allowed_signers` line.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Signer {
    pub line: usize,
    pub principals: String,
    pub namespaces: Option<String>,
    pub valid_after: Option<String>,
    pub valid_before: Option<String>,
    pub key_type: String,
    pub key: String,
}

fn is_key_type(token: &str) -> bool {
    token.starts_with("ssh-") || token.starts_with("ecdsa-") || token.starts_with("sk-")
}

/// Split on whitespace outside double quotes. `None` on an unterminated quote.
fn fields(line: &str) -> Option<Vec<&str>> {
    let mut out = Vec::new();
    let mut start: Option<usize> = None;
    let mut quoted = false;
    for (index, c) in line.char_indices() {
        match c {
            '"' => {
                quoted = !quoted;
                start.get_or_insert(index);
            }
            c if c.is_whitespace() && !quoted => {
                if let Some(s) = start.take() {
                    out.push(&line[s..index]);
                }
            }
            _ => {
                start.get_or_insert(index);
            }
        }
    }
    if quoted {
        return None;
    }
    if let Some(s) = start {
        out.push(&line[s..]);
    }
    Some(out)
}

/// Split an options token on commas outside quotes.
fn option_items(options: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    let mut quoted = false;
    for (index, c) in options.char_indices() {
        match c {
            '"' => quoted = !quoted,
            ',' if !quoted => {
                out.push(&options[start..index]);
                start = index + 1;
            }
            _ => {}
        }
    }
    out.push(&options[start..]);
    out
}

fn valid_window(value: &str) -> bool {
    let digits = value.strip_suffix('Z').unwrap_or(value);
    matches!(digits.len(), 8 | 12 | 14) && digits.bytes().all(|b| b.is_ascii_digit())
}

/// Parse `allowed_signers`. Refuses unquoted option values, naming the line.
pub fn parse_allowed_signers(text: &str) -> Result<Vec<Signer>, TrustError> {
    let mut signers = Vec::new();
    for (index, raw) in text.lines().enumerate() {
        let line_no = index + 1;
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let tokens =
            fields(line).ok_or_else(|| err(ALLOWED_FILE, line_no, "unterminated double quote"))?;
        if tokens.len() < 3 {
            return Err(err(
                ALLOWED_FILE,
                line_no,
                "expected `<principals> [options] <key-type> <key>`",
            ));
        }
        let (options, rest) = if is_key_type(tokens[1]) {
            (None, &tokens[1..])
        } else {
            (Some(tokens[1]), &tokens[2..])
        };
        if rest.len() < 2 || !is_key_type(rest[0]) {
            return Err(err(
                ALLOWED_FILE,
                line_no,
                "missing or unrecognised key type",
            ));
        }
        let mut signer = Signer {
            line: line_no,
            principals: tokens[0].to_owned(),
            namespaces: None,
            valid_after: None,
            valid_before: None,
            key_type: rest[0].to_owned(),
            key: rest[1].to_owned(),
        };
        for item in options.map(option_items).unwrap_or_default() {
            let Some((name, value)) = item.split_once('=') else {
                continue; // flag option such as cert-authority
            };
            let unquoted = value
                .strip_prefix('"')
                .and_then(|v| v.strip_suffix('"'))
                .filter(|v| !v.contains('"'));
            let Some(unquoted) = unquoted else {
                return Err(err(
                    ALLOWED_FILE,
                    line_no,
                    format!("option `{name}` value must be quoted: {name}=\"...\""),
                ));
            };
            match name {
                "namespaces" => signer.namespaces = Some(unquoted.to_owned()),
                "valid-after" | "valid-before" => {
                    if !valid_window(unquoted) {
                        return Err(err(
                            ALLOWED_FILE,
                            line_no,
                            format!(
                                "option `{name}` must be YYYYMMDD[HHMM[SS]][Z], got `{unquoted}`"
                            ),
                        ));
                    }
                    if name == "valid-after" {
                        signer.valid_after = Some(unquoted.to_owned());
                    } else {
                        signer.valid_before = Some(unquoted.to_owned());
                    }
                }
                _ => {}
            }
        }
        signers.push(signer);
    }
    Ok(signers)
}

/// Parse `revoked`: a list of public keys (`<type> <base64> [comment]`).
pub fn parse_revoked(text: &str) -> Result<Vec<String>, TrustError> {
    let mut keys = Vec::new();
    for (index, raw) in text.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.split_whitespace();
        match (parts.next(), parts.next()) {
            (Some(kind), Some(key)) if is_key_type(kind) => keys.push(format!("{kind} {key}")),
            _ => {
                return Err(err(
                    REVOKED_FILE,
                    index + 1,
                    "expected a public key `<key-type> <base64>`",
                ))
            }
        }
    }
    Ok(keys)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Policy {
    /// Free-form mode name. Unknown values are not rejected here; consumers
    /// treat anything they do not recognise as `warn` (the default).
    pub enforcement: String,
    pub max_review: String,
    pub audited_principals: Vec<String>,
    pub canonical_principals: Vec<String>,
    pub canonical_min_signers: u32,
    pub capture_max_bytes: u64,
}

impl Default for Policy {
    fn default() -> Policy {
        Policy {
            enforcement: DEFAULT_ENFORCEMENT.to_owned(),
            max_review: DEFAULT_MAX_REVIEW.to_owned(),
            audited_principals: vec![DEFAULT_AUDITED_PRINCIPALS.to_owned()],
            canonical_principals: Vec::new(),
            canonical_min_signers: 1,
            capture_max_bytes: DEFAULT_CAPTURE_MAX_BYTES,
        }
    }
}

impl Policy {
    /// `max_review` in days (`180d` form).
    pub fn max_review_days(&self) -> u32 {
        self.max_review
            .strip_suffix('d')
            .and_then(|d| d.parse().ok())
            .unwrap_or(180)
    }

    pub fn to_json(&self) -> Value {
        let list = |items: &[String]| {
            Value::Array(items.iter().map(|s| Value::String(s.clone())).collect())
        };
        Value::Object(vec![
            ("_type".into(), Value::String(POLICY_TYPE.into())),
            (
                "enforcement".into(),
                Value::String(self.enforcement.clone()),
            ),
            ("max_review".into(), Value::String(self.max_review.clone())),
            (
                "levels".into(),
                Value::Object(vec![
                    (
                        "audited".into(),
                        Value::Object(vec![("principals".into(), list(&self.audited_principals))]),
                    ),
                    (
                        "canonical".into(),
                        Value::Object(vec![
                            ("principals".into(), list(&self.canonical_principals)),
                            (
                                "min_signers".into(),
                                Value::Number(self.canonical_min_signers.to_string()),
                            ),
                        ]),
                    ),
                ]),
            ),
            (
                "capture_max_bytes".into(),
                Value::Number(self.capture_max_bytes.to_string()),
            ),
        ])
    }
}

fn string_list(value: &Value, what: &str) -> Result<Vec<String>, TrustError> {
    let items = value.as_array().ok_or_else(|| {
        err(
            POLICY_FILE,
            0,
            format!("{what} must be an array of strings"),
        )
    })?;
    items
        .iter()
        .map(|item| {
            item.as_str().map(str::to_owned).ok_or_else(|| {
                err(
                    POLICY_FILE,
                    0,
                    format!("{what} must be an array of strings"),
                )
            })
        })
        .collect()
}

fn number<T: std::str::FromStr>(value: &Value, what: &str) -> Result<T, TrustError> {
    match value {
        Value::Number(literal) => literal.parse().map_err(|_| {
            err(
                POLICY_FILE,
                0,
                format!("{what} must be a non-negative integer"),
            )
        }),
        _ => Err(err(POLICY_FILE, 0, format!("{what} must be a number"))),
    }
}

/// Parse `policy.json`; unknown fields are ignored, absent fields default.
pub fn parse_policy(text: &str) -> Result<Policy, TrustError> {
    let doc = json::parse(text).map_err(|e| err(POLICY_FILE, 0, format!("not valid JSON: {e}")))?;
    if !matches!(doc, Value::Object(_)) {
        return Err(err(POLICY_FILE, 0, "must be a JSON object"));
    }
    if let Some(kind) = doc.get("_type") {
        if kind.as_str() != Some(POLICY_TYPE) {
            return Err(err(POLICY_FILE, 0, format!("_type must be {POLICY_TYPE}")));
        }
    }
    let mut policy = Policy::default();
    if let Some(v) = doc.get("enforcement") {
        policy.enforcement = v
            .as_str()
            .filter(|s| !s.is_empty())
            .ok_or_else(|| err(POLICY_FILE, 0, "enforcement must be a non-empty string"))?
            .to_owned();
    }
    if let Some(v) = doc.get("max_review") {
        let text = v
            .as_str()
            .filter(|s| {
                s.strip_suffix('d')
                    .is_some_and(|d| !d.is_empty() && d.bytes().all(|b| b.is_ascii_digit()))
            })
            .ok_or_else(|| err(POLICY_FILE, 0, "max_review must look like `180d`"))?;
        policy.max_review = text.to_owned();
    }
    if let Some(levels) = doc.get("levels") {
        if let Some(v) = levels.get("audited").and_then(|a| a.get("principals")) {
            policy.audited_principals = string_list(v, "levels.audited.principals")?;
        }
        if let Some(canonical) = levels.get("canonical") {
            if let Some(v) = canonical.get("principals") {
                policy.canonical_principals = string_list(v, "levels.canonical.principals")?;
            }
            if let Some(v) = canonical.get("min_signers") {
                let n: u32 = number(v, "levels.canonical.min_signers")?;
                if n == 0 {
                    return Err(err(
                        POLICY_FILE,
                        0,
                        "levels.canonical.min_signers must be >= 1",
                    ));
                }
                policy.canonical_min_signers = n;
            }
        }
    }
    if let Some(v) = doc.get("capture_max_bytes") {
        policy.capture_max_bytes = number(v, "capture_max_bytes")?;
    }
    Ok(policy)
}

/// Everything under `<configRoot>/seal/` the verifier reads.
#[derive(Debug, Clone)]
pub struct Trust {
    pub signers: Vec<Signer>,
    pub revoked: Vec<String>,
    pub policy: Policy,
}

fn read_optional(path: &Path, file: &'static str) -> Result<Option<String>, TrustError> {
    match fs::read_to_string(path) {
        Ok(text) => Ok(Some(text)),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(e) => Err(err(file, 0, format!("cannot read {}: {e}", path.display()))),
    }
}

/// Load trust from `dir`; absent files yield empty lists and default policy.
pub fn load(dir: &Path) -> Result<Trust, TrustError> {
    let signers = match read_optional(&dir.join(ALLOWED_FILE), ALLOWED_FILE)? {
        Some(text) => parse_allowed_signers(&text)?,
        None => Vec::new(),
    };
    let revoked = match read_optional(&dir.join(REVOKED_FILE), REVOKED_FILE)? {
        Some(text) => parse_revoked(&text)?,
        None => Vec::new(),
    };
    let policy = match read_optional(&dir.join(POLICY_FILE), POLICY_FILE)? {
        Some(text) => parse_policy(&text)?,
        None => Policy::default(),
    };
    Ok(Trust {
        signers,
        revoked,
        policy,
    })
}

/// Identity inputs for `init`: the enrolled instance id and org when this
/// machine is enrolled, else `None` (mint / `local`).
#[derive(Debug, Clone, Default)]
pub struct Enrolled {
    pub instance: Option<String>,
    pub org: Option<String>,
}

impl Enrolled {
    /// Resolve from the process environment: the client certificate's
    /// instance id, then `LOAM_FEDERATION_ORG` / `org` in `config.json`.
    pub fn from_environment() -> Enrolled {
        let instance = crate::provisioning::configured_identity_root()
            .ok()
            .and_then(|root| fs::read(root.join("client.pem")).ok())
            .and_then(|pem| crate::provisioning::certificate_instance_id(&pem).ok());
        let clean = |s: String| {
            let t = s.trim().to_owned();
            (!t.is_empty()).then_some(t)
        };
        let org = std::env::var("LOAM_FEDERATION_ORG")
            .ok()
            .and_then(clean)
            .or_else(|| {
                crate::provisioning::read_configured_config()
                    .ok()
                    .flatten()
                    .and_then(|c| c.get("org").and_then(Value::as_str).map(str::to_owned))
                    .and_then(clean)
            });
        Enrolled { instance, org }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InitReport {
    pub principal: String,
    pub created: Vec<&'static str>,
}

fn principal_ok(principal: &str) -> bool {
    !principal.is_empty()
        && !principal.chars().any(|c| {
            c.is_whitespace() || c.is_control() || matches!(c, '"' | ',' | '*' | '?' | '!')
        })
}

fn create_private_dir(dir: &Path) -> Result<(), String> {
    if dir.is_dir() {
        return Ok(());
    }
    fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(dir, fs::Permissions::from_mode(0o700))
            .map_err(|e| format!("cannot restrict {}: {e}", dir.display()))?;
    }
    Ok(())
}

fn write_new(path: &Path, bytes: &[u8]) -> Result<(), String> {
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .map_err(|e| format!("cannot create {}: {e}", path.display()))?;
    file.write_all(bytes)
        .map_err(|e| format!("cannot write {}: {e}", path.display()))
}

fn append_line(path: &Path, line: &str) -> Result<(), String> {
    let existing = fs::read_to_string(path).unwrap_or_default();
    let mut file = fs::OpenOptions::new()
        .append(true)
        .create(true)
        .open(path)
        .map_err(|e| format!("cannot open {}: {e}", path.display()))?;
    let mut text = String::new();
    if !existing.is_empty() && !existing.ends_with('\n') {
        text.push('\n');
    }
    text.push_str(line);
    text.push('\n');
    file.write_all(text.as_bytes())
        .map_err(|e| format!("cannot write {}: {e}", path.display()))
}

fn resolve_instance(dir: &Path, enrolled: &Enrolled) -> Result<(String, bool), String> {
    let path = dir.join(INSTANCE_FILE);
    match fs::read_to_string(&path) {
        Ok(text) => {
            let id = text.trim().to_owned();
            if !crate::provisioning::is_valid_instance_id(&id) {
                return Err(format!(
                    "{} does not hold a valid instance id; remove it to mint a new one",
                    path.display()
                ));
            }
            Ok((id, false))
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            let id = match &enrolled.instance {
                Some(id) => id.clone(),
                None => crate::enrollment_auto::generate_instance_id()
                    .map_err(|f| format!("cannot mint an instance id: {}", f.code()))?,
            };
            write_new(&path, format!("{id}\n").as_bytes())?;
            Ok((id, true))
        }
        Err(e) => Err(format!("cannot read {}: {e}", path.display())),
    }
}

/// `loam seal trust init`: idempotent, never prompts, never overwrites.
pub fn init(dir: &Path, enrolled: &Enrolled, keygen: &Path) -> Result<InitReport, String> {
    create_private_dir(dir)?;
    // A malformed existing trust file is the operator's to fix, not ours to
    // append to.
    let trust = load(dir).map_err(|e| e.to_string())?;
    let mut created = Vec::new();

    let (instance, minted) = resolve_instance(dir, enrolled)?;
    if minted {
        created.push(INSTANCE_FILE);
    }
    let org = enrolled.org.clone().unwrap_or_else(|| "local".to_owned());
    let principal = format!("agent.{instance}@{org}");
    if !principal_ok(&principal) {
        return Err(format!(
            "org `{org}` cannot appear in a signer principal (no whitespace, quotes or commas)"
        ));
    }

    let key = dir.join(KEY_FILE);
    let public_path = dir.join(PUBLIC_FILE);
    if !key.exists() {
        let output = Command::new(keygen)
            .args(["-q", "-t", "ed25519", "-N", "", "-C", &principal, "-f"])
            .arg(&key)
            .output()
            .map_err(|e| format!("cannot run {}: {e}", keygen.display()))?;
        if !output.status.success() {
            return Err(format!(
                "ssh-keygen failed: {}",
                String::from_utf8_lossy(&output.stderr).trim()
            ));
        }
        created.push(KEY_FILE);
        created.push(PUBLIC_FILE);
    } else if !public_path.exists() {
        let output = Command::new(keygen)
            .args(["-y", "-f"])
            .arg(&key)
            .output()
            .map_err(|e| format!("cannot run {}: {e}", keygen.display()))?;
        if !output.status.success() {
            return Err(format!(
                "cannot derive the public key from {}: {}",
                key.display(),
                String::from_utf8_lossy(&output.stderr).trim()
            ));
        }
        write_new(&public_path, &output.stdout)?;
        created.push(PUBLIC_FILE);
    }

    let public = fs::read_to_string(&public_path)
        .map_err(|e| format!("cannot read {}: {e}", public_path.display()))?;
    let mut parts = public.split_whitespace();
    let (Some(kind), Some(material)) = (parts.next(), parts.next()) else {
        return Err(format!("{} is not a public key", public_path.display()));
    };
    let present = trust
        .signers
        .iter()
        .any(|s| s.principals == principal && s.key == material);
    if !present {
        let today = chrono::Utc::now().format("%Y%m%dZ");
        append_line(
            &dir.join(ALLOWED_FILE),
            &format!(
                "{principal} namespaces=\"{}\",valid-after=\"{today}\" {kind} {material}",
                sshsig::NAMESPACE
            ),
        )?;
        created.push(ALLOWED_FILE);
    }

    let policy_path = dir.join(POLICY_FILE);
    if !policy_path.exists() {
        let mut body = pretty_policy(&Policy::default());
        body.push('\n');
        write_new(&policy_path, body.as_bytes())?;
        created.push(POLICY_FILE);
    }
    Ok(InitReport { principal, created })
}

fn pretty_policy(policy: &Policy) -> String {
    let list = |items: &[String]| {
        let quoted: Vec<String> = items
            .iter()
            .map(|i| Value::String(i.clone()).to_json())
            .collect();
        format!("[{}]", quoted.join(", "))
    };
    format!(
        "{{\n  \"_type\": \"{POLICY_TYPE}\",\n  \"enforcement\": {},\n  \"max_review\": {},\n  \"levels\": {{\n    \"audited\": {{ \"principals\": {} }},\n    \"canonical\": {{ \"principals\": {}, \"min_signers\": {} }}\n  }},\n  \"capture_max_bytes\": {}\n}}",
        Value::String(policy.enforcement.clone()).to_json(),
        Value::String(policy.max_review.clone()).to_json(),
        list(&policy.audited_principals),
        list(&policy.canonical_principals),
        policy.canonical_min_signers,
        policy.capture_max_bytes
    )
}

fn base64_nopad(bytes: &[u8]) -> String {
    let encoded = crate::provisioning::base64_encode(bytes);
    String::from_utf8_lossy(&encoded)
        .trim_end_matches('=')
        .to_owned()
}

/// OpenSSH-style `SHA256:<base64>` fingerprint of a public key's base64 blob.
pub fn fingerprint(key_base64: &str) -> Option<String> {
    let blob = crate::provisioning::base64_decode(key_base64)?;
    if blob.is_empty() {
        return None;
    }
    let hex = sha256::hex(&blob);
    let digest: Vec<u8> = (0..hex.len())
        .step_by(2)
        .filter_map(|i| u8::from_str_radix(&hex[i..i + 2], 16).ok())
        .collect();
    Some(format!("SHA256:{}", base64_nopad(&digest)))
}

/// `loam seal trust add`: append a quoted line; returns the fingerprint.
/// `pubkey` is the key text (`<type> <base64> [comment]`) or a path to a
/// `.pub` file.
pub fn add(dir: &Path, principal: &str, pubkey: &str) -> Result<String, String> {
    if !principal_ok(principal) {
        return Err(format!(
            "principal `{principal}` must be non-empty with no whitespace, quotes or commas"
        ));
    }
    let text = match fs::read_to_string(pubkey) {
        Ok(text) if Path::new(pubkey).is_file() => text,
        _ => pubkey.to_owned(),
    };
    let mut parts = text.split_whitespace();
    let (Some(kind), Some(material)) = (parts.next(), parts.next()) else {
        return Err("pubkey must be `<key-type> <base64>` or a path to a .pub file".into());
    };
    if !is_key_type(kind) {
        return Err(format!("unrecognised key type `{kind}`"));
    }
    let print = fingerprint(material).ok_or("pubkey is not valid base64 key material")?;
    create_private_dir(dir)?;
    let trust = load(dir).map_err(|e| e.to_string())?;
    if trust
        .signers
        .iter()
        .any(|s| s.principals == principal && s.key == material)
    {
        return Ok(print);
    }
    let today = chrono::Utc::now().format("%Y%m%dZ");
    append_line(
        &dir.join(ALLOWED_FILE),
        &format!(
            "{principal} namespaces=\"{}\",valid-after=\"{today}\" {kind} {material}",
            sshsig::NAMESPACE
        ),
    )?;
    Ok(print)
}

/// The `<configRoot>/seal` directory for this process.
pub fn seal_dir() -> Result<PathBuf, String> {
    crate::provisioning::configured_config_root()
        .map(|root| root.join("seal"))
        .ok_or_else(|| "no loam config directory resolves; set LOAM_CONFIG_DIR".to_owned())
}

pub fn run(mut args: impl Iterator<Item = String>) -> i32 {
    let verb = args.next();
    let rest: Vec<String> = args.collect();
    match (verb.as_deref(), rest.as_slice()) {
        (Some("init"), []) => cmd_init(),
        (Some("add"), [principal, pubkey]) => cmd_add(principal, pubkey),
        (Some("show"), []) => cmd_show(),
        _ => usage(),
    }
}

fn usage() -> i32 {
    eprintln!(
        "Usage:\n  loam seal trust init\n  loam seal trust add <principal> <pubkey|pubkey-file>\n  loam seal trust show"
    );
    EXIT_USAGE
}

fn cmd_init() -> i32 {
    let dir = match seal_dir() {
        Ok(dir) => dir,
        Err(e) => {
            eprintln!("loam seal trust init: {e}");
            return EXIT_USAGE;
        }
    };
    match init(
        &dir,
        &Enrolled::from_environment(),
        &sshsig::keygen_binary(),
    ) {
        Ok(report) => {
            let created = report
                .created
                .iter()
                .map(|name| Value::String((*name).to_owned()))
                .collect();
            println!(
                "{}",
                Value::Object(vec![
                    ("principal".into(), Value::String(report.principal)),
                    ("created".into(), Value::Array(created)),
                ])
                .to_json()
            );
            EXIT_OK
        }
        Err(e) => {
            eprintln!("loam seal trust init: {e}");
            EXIT_REFUSED
        }
    }
}

fn cmd_add(principal: &str, pubkey: &str) -> i32 {
    let dir = match seal_dir() {
        Ok(dir) => dir,
        Err(e) => {
            eprintln!("loam seal trust add: {e}");
            return EXIT_USAGE;
        }
    };
    match add(&dir, principal, pubkey) {
        Ok(print) => {
            println!("{print}");
            EXIT_OK
        }
        Err(e) => {
            eprintln!("loam seal trust add: {e}");
            EXIT_REFUSED
        }
    }
}

fn cmd_show() -> i32 {
    let dir = match seal_dir() {
        Ok(dir) => dir,
        Err(e) => {
            eprintln!("loam seal trust show: {e}");
            return EXIT_USAGE;
        }
    };
    let trust = match load(&dir) {
        Ok(trust) => trust,
        Err(e) => {
            eprintln!("loam seal trust show: {e}");
            return EXIT_USAGE;
        }
    };
    let opt = |v: &Option<String>| v.clone().map_or(Value::Null, Value::String);
    let principals = trust
        .signers
        .iter()
        .map(|s| {
            Value::Object(vec![
                ("principal".into(), Value::String(s.principals.clone())),
                (
                    "fingerprint".into(),
                    fingerprint(&s.key).map_or(Value::Null, Value::String),
                ),
                ("namespaces".into(), opt(&s.namespaces)),
                ("valid_after".into(), opt(&s.valid_after)),
                ("valid_before".into(), opt(&s.valid_before)),
            ])
        })
        .collect();
    let revoked = trust
        .revoked
        .iter()
        .map(|k| {
            let material = k.split_whitespace().nth(1).unwrap_or_default();
            Value::String(fingerprint(material).unwrap_or_else(|| k.clone()))
        })
        .collect();
    println!(
        "{}",
        Value::Object(vec![
            ("principals".into(), Value::Array(principals)),
            ("revoked".into(), Value::Array(revoked)),
            ("policy".into(), trust.policy.to_json()),
        ])
        .to_json()
    );
    EXIT_OK
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::seal::sshsig::{keygen_for_tests, test_support};

    struct Tmp(PathBuf);
    impl Tmp {
        fn new(label: &str) -> Tmp {
            let dir = std::env::temp_dir().join(format!(
                "loam-trust-{label}-{}-{}",
                std::process::id(),
                std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map_or(0, |d| d.subsec_nanos())
            ));
            fs::create_dir_all(&dir).unwrap();
            Tmp(dir)
        }
    }
    impl Drop for Tmp {
        fn drop(&mut self) {
            for _ in 0..5 {
                if fs::remove_dir_all(&self.0).is_ok() {
                    return;
                }
                std::thread::sleep(std::time::Duration::from_millis(50));
            }
        }
    }

    const KEY: &str = "AAAAC3NzaC1lZDI1NTE5AAAAIOMqqnkVzrm0SzG4gXNuIkJvIrrvNS7QCRgnVTMmWqH1";

    #[test]
    fn unquoted_window_is_refused_naming_the_line() {
        let text = format!(
            "# comment\n\na@local namespaces=\"loam-seal\",valid-after=\"20260101\" ssh-ed25519 {KEY}\nb@local namespaces=\"loam-seal\",valid-after=20260101 ssh-ed25519 {KEY}\n"
        );
        let error = parse_allowed_signers(&text).unwrap_err();
        assert_eq!(error.line, 4);
        assert!(error.to_string().contains("allowed_signers line 4"));
        assert!(error.message.contains("valid-after"));
    }

    #[test]
    fn quoted_lines_parse_with_windows_and_optional_options() {
        let text = format!(
            "a@local namespaces=\"loam-seal\",valid-after=\"20260101\",valid-before=\"20270101Z\" ssh-ed25519 {KEY} c\nb@x ssh-ed25519 {KEY}\n"
        );
        let signers = parse_allowed_signers(&text).unwrap();
        assert_eq!(signers.len(), 2);
        assert_eq!(signers[0].valid_after.as_deref(), Some("20260101"));
        assert_eq!(signers[0].valid_before.as_deref(), Some("20270101Z"));
        assert_eq!(signers[0].namespaces.as_deref(), Some("loam-seal"));
        assert_eq!(signers[1].valid_after, None);
        assert!(parse_allowed_signers("a@l namespaces=\"loam-seal ssh-ed25519 K\n").is_err());
        assert!(
            parse_allowed_signers(&format!("a@l valid-after=\"soon\" ssh-ed25519 {KEY}\n"))
                .is_err()
        );
    }

    #[test]
    fn policy_defaults_and_parsing() {
        let default = Policy::default();
        assert_eq!(default.max_review_days(), 180);
        assert_eq!(default.capture_max_bytes, 262_144);
        let parsed = parse_policy(&pretty_policy(&default)).unwrap();
        assert_eq!(parsed, default);
        let custom = parse_policy(
            r#"{"_type":"loam.seal-policy/v1","unknown":1,"max_review":"30d","levels":{"canonical":{"principals":["a@x"],"min_signers":2}},"capture_max_bytes":10}"#,
        )
        .unwrap();
        assert_eq!(custom.max_review_days(), 30);
        assert_eq!(custom.canonical_min_signers, 2);
        assert_eq!(custom.capture_max_bytes, 10);
        assert_eq!(custom.audited_principals, default.audited_principals);
        assert!(parse_policy(r#"{"_type":"other/v1"}"#).is_err());
        assert!(parse_policy(r#"{"max_review":"soon"}"#).is_err());
        assert!(parse_policy(r#"{"levels":{"canonical":{"min_signers":0}}}"#).is_err());
        assert!(parse_policy("[]").is_err());
    }

    #[test]
    fn revoked_parses_keys_and_rejects_junk() {
        let keys = parse_revoked(&format!("# k\nssh-ed25519 {KEY} comment\n")).unwrap();
        assert_eq!(keys, vec![format!("ssh-ed25519 {KEY}")]);
        assert_eq!(parse_revoked("garbage\n").unwrap_err().line, 1);
    }

    #[test]
    fn fingerprint_matches_the_openssh_form() {
        let print = fingerprint(KEY).unwrap();
        assert!(print.starts_with("SHA256:"));
        assert_eq!(print.len(), "SHA256:".len() + 43);
        assert!(fingerprint("!!!").is_none());
        if let Some(bin) = keygen_for_tests() {
            let tmp = Tmp::new("fp");
            let pub_path = tmp.0.join("k.pub");
            fs::write(&pub_path, format!("ssh-ed25519 {KEY}\n")).unwrap();
            let out = Command::new(bin)
                .args(["-l", "-f"])
                .arg(&pub_path)
                .output()
                .unwrap();
            let line = String::from_utf8_lossy(&out.stdout);
            assert!(line.contains(&print), "{line} vs {print}");
        }
    }

    #[test]
    fn init_is_idempotent_and_adds_a_quoted_line() {
        let Some(bin) = keygen_for_tests() else {
            eprintln!("no capable ssh-keygen; init needs one");
            return;
        };
        let tmp = Tmp::new("init");
        let dir = tmp.0.join("seal");
        let enrolled = Enrolled::default();
        let first = init(&dir, &enrolled, &bin).unwrap();
        assert!(first.principal.starts_with("agent."));
        assert!(first.principal.ends_with("@local"));
        assert_eq!(
            first.created,
            vec![
                INSTANCE_FILE,
                KEY_FILE,
                PUBLIC_FILE,
                ALLOWED_FILE,
                POLICY_FILE
            ]
        );
        let snapshot = |name: &str| fs::read(dir.join(name)).unwrap();
        let before: Vec<Vec<u8>> = [
            INSTANCE_FILE,
            KEY_FILE,
            PUBLIC_FILE,
            ALLOWED_FILE,
            POLICY_FILE,
        ]
        .iter()
        .map(|n| snapshot(n))
        .collect();

        // A different enrolled identity on re-run must not change anything.
        let again = init(
            &dir,
            &Enrolled {
                instance: Some("01ARZ3NDEKTSV4RRFFQ69G5FAV".into()),
                org: None,
            },
            &bin,
        )
        .unwrap();
        assert!(again.created.is_empty());
        assert_eq!(again.principal, first.principal);
        let after: Vec<Vec<u8>> = [
            INSTANCE_FILE,
            KEY_FILE,
            PUBLIC_FILE,
            ALLOWED_FILE,
            POLICY_FILE,
        ]
        .iter()
        .map(|n| snapshot(n))
        .collect();
        assert_eq!(before, after);

        let trust = load(&dir).unwrap();
        assert_eq!(trust.signers.len(), 1);
        assert_eq!(trust.signers[0].namespaces.as_deref(), Some("loam-seal"));
        assert!(trust.signers[0].valid_after.is_some());
        assert_eq!(trust.policy, Policy::default());

        // The key really signs and verifies under the generated line.
        let sig = sshsig::sign(&bin, &dir.join(KEY_FILE), b"hello").unwrap();
        let now = sshsig::verify_time_utc(&chrono::Utc::now().to_rfc3339()).unwrap();
        // valid-after is today's date at 00:00 UTC (explicit `Z`), so now is inside it.
        sshsig::verify(
            &bin,
            &dir.join(ALLOWED_FILE),
            &first.principal,
            &sig,
            b"hello",
            &now,
            None,
        )
        .unwrap();
    }

    #[test]
    fn init_uses_the_enrolled_instance_and_org_once() {
        let Some(bin) = keygen_for_tests() else {
            return;
        };
        let tmp = Tmp::new("enrolled");
        let dir = tmp.0.join("seal");
        let report = init(
            &dir,
            &Enrolled {
                instance: Some("01ARZ3NDEKTSV4RRFFQ69G5FAV".into()),
                org: Some("acme".into()),
            },
            &bin,
        )
        .unwrap();
        assert_eq!(report.principal, "agent.01ARZ3NDEKTSV4RRFFQ69G5FAV@acme");
        assert_eq!(
            fs::read_to_string(dir.join(INSTANCE_FILE)).unwrap(),
            "01ARZ3NDEKTSV4RRFFQ69G5FAV\n"
        );
    }

    #[test]
    fn init_refuses_a_bad_org_and_a_malformed_trust_file() {
        let Some(bin) = keygen_for_tests() else {
            return;
        };
        let tmp = Tmp::new("bad");
        let dir = tmp.0.join("seal");
        let bad = init(
            &dir,
            &Enrolled {
                instance: None,
                org: Some("two words".into()),
            },
            &bin,
        );
        assert!(bad.unwrap_err().contains("org"));

        let dir2 = tmp.0.join("seal2");
        fs::create_dir_all(&dir2).unwrap();
        fs::write(
            dir2.join(ALLOWED_FILE),
            format!("a@l valid-after=20260101 ssh-ed25519 {KEY}\n"),
        )
        .unwrap();
        let error = init(&dir2, &Enrolled::default(), &bin).unwrap_err();
        assert!(error.contains("allowed_signers line 1"), "{error}");
        assert!(!dir2.join(KEY_FILE).exists());
    }

    #[test]
    fn init_without_a_keygen_binary_fails_cleanly() {
        let tmp = Tmp::new("nokeygen");
        let stub = test_support::stub_without_y(&tmp.0);
        let error = init(&tmp.0.join("seal"), &Enrolled::default(), &stub).unwrap_err();
        assert!(error.contains("ssh-keygen failed"), "{error}");
        let missing = init(
            &tmp.0.join("seal3"),
            &Enrolled::default(),
            Path::new("/no/such/keygen"),
        )
        .unwrap_err();
        assert!(missing.contains("cannot run"), "{missing}");
    }

    #[test]
    fn add_appends_a_quoted_line_and_prints_the_fingerprint() {
        let tmp = Tmp::new("add");
        let dir = tmp.0.join("seal");
        let print = add(&dir, "alice@org", &format!("ssh-ed25519 {KEY} alice")).unwrap();
        assert_eq!(print, fingerprint(KEY).unwrap());
        let text = fs::read_to_string(dir.join(ALLOWED_FILE)).unwrap();
        assert!(text.contains("namespaces=\"loam-seal\",valid-after=\""));
        assert!(parse_allowed_signers(&text).is_ok());
        // Same principal and key again: no duplicate line.
        add(&dir, "alice@org", &format!("ssh-ed25519 {KEY}")).unwrap();
        assert_eq!(
            fs::read_to_string(dir.join(ALLOWED_FILE))
                .unwrap()
                .lines()
                .count(),
            1
        );
        // A .pub file path works too.
        let file = tmp.0.join("bob.pub");
        fs::write(&file, format!("ssh-ed25519 {KEY} bob\n")).unwrap();
        add(&dir, "bob@org", file.to_str().unwrap()).unwrap();
        assert_eq!(load(&dir).unwrap().signers.len(), 2);

        assert!(add(&dir, "bad principal", &format!("ssh-ed25519 {KEY}")).is_err());
        assert!(add(&dir, "c@org", "nonsense").is_err());
        assert!(add(&dir, "c@org", "ssh-ed25519 !!!").is_err());
    }

    #[test]
    fn add_preserves_a_file_without_a_trailing_newline() {
        let tmp = Tmp::new("nonl");
        let dir = tmp.0.join("seal");
        fs::create_dir_all(&dir).unwrap();
        fs::write(
            dir.join(ALLOWED_FILE),
            format!("a@l namespaces=\"loam-seal\" ssh-ed25519 {KEY}"),
        )
        .unwrap();
        add(&dir, "b@l", &format!("ssh-ed25519 {KEY}")).unwrap();
        assert_eq!(load(&dir).unwrap().signers.len(), 2);
    }

    #[test]
    fn load_with_no_files_yields_defaults() {
        let tmp = Tmp::new("empty");
        let trust = load(&tmp.0.join("missing")).unwrap();
        assert!(trust.signers.is_empty() && trust.revoked.is_empty());
        assert_eq!(trust.policy, Policy::default());
    }

    /// Restores an environment variable on drop, panic or not.
    struct EnvGuard(&'static str, Option<std::ffi::OsString>);
    impl EnvGuard {
        fn set(name: &'static str, value: impl AsRef<std::ffi::OsStr>) -> EnvGuard {
            let prior = std::env::var_os(name);
            std::env::set_var(name, value);
            EnvGuard(name, prior)
        }
    }
    impl Drop for EnvGuard {
        fn drop(&mut self) {
            match self.1.take() {
                Some(v) => std::env::set_var(self.0, v),
                None => std::env::remove_var(self.0),
            }
        }
    }

    #[test]
    fn principals_with_pattern_metacharacters_are_refused() {
        let tmp = Tmp::new("meta");
        let dir = tmp.0.join("seal");
        for bad in ["*", "!a@org", "a?@org", "*@org"] {
            assert!(
                add(&dir, bad, &format!("ssh-ed25519 {KEY}")).is_err(),
                "{bad}"
            );
        }
    }

    #[test]
    fn init_window_is_explicit_utc_whatever_the_reader_time_zone() {
        let Some(bin) = keygen_for_tests() else {
            return;
        };
        let _guard = crate::env_lock();
        let tmp = Tmp::new("tz");
        let dir = tmp.0.join("seal");
        let first = init(&dir, &Enrolled::default(), &bin).unwrap();
        let text = fs::read_to_string(dir.join(ALLOWED_FILE)).unwrap();
        assert!(
            text.contains("Z\" "),
            "valid-after must carry an explicit Z: {text}"
        );
        let sig = sshsig::sign(&bin, &dir.join(KEY_FILE), b"hello").unwrap();
        let start = format!("{}0001Z", chrono::Utc::now().format("%Y%m%d"));
        // A negative-offset reader reads a Z-less date as local midnight, hours
        // after the UTC start; with `Z` the verdict is the same everywhere.
        #[cfg(unix)]
        let _tz = EnvGuard::set("TZ", "America/New_York");
        sshsig::verify(
            &bin,
            &dir.join(ALLOWED_FILE),
            &first.principal,
            &sig,
            b"hello",
            &start,
            None,
        )
        .unwrap();
    }

    #[test]
    fn cli_show_exits_2_on_an_unquoted_window() {
        let _guard = crate::env_lock();
        let tmp = Tmp::new("cli");
        let _cfg = EnvGuard::set("LOAM_CONFIG_DIR", &tmp.0);
        let dir = tmp.0.join("seal");
        fs::create_dir_all(&dir).unwrap();
        fs::write(
            dir.join(ALLOWED_FILE),
            format!("a@l namespaces=\"loam-seal\",valid-after=20260101 ssh-ed25519 {KEY}\n"),
        )
        .unwrap();
        let code = run(["show".to_owned()].into_iter());
        fs::write(
            dir.join(ALLOWED_FILE),
            format!("a@l namespaces=\"loam-seal\",valid-after=\"20260101\" ssh-ed25519 {KEY}\n"),
        )
        .unwrap();
        let ok = run(["show".to_owned()].into_iter());
        let usage = run(["bogus".to_owned()].into_iter());
        assert_eq!(code, EXIT_USAGE);
        assert_eq!(ok, EXIT_OK);
        assert_eq!(usage, EXIT_USAGE);
    }

    #[test]
    fn cli_init_and_add_run_under_pinned_env() {
        let Some(bin) = keygen_for_tests() else {
            return;
        };
        let _guard = crate::env_lock();
        let tmp = Tmp::new("cli-init");
        let _cfg = EnvGuard::set("LOAM_CONFIG_DIR", &tmp.0);
        let _kg = EnvGuard::set("LOAM_SSH_KEYGEN", &bin);
        let dir = tmp.0.join("seal");
        assert_eq!(run(["init".to_owned()].into_iter()), EXIT_OK);
        for name in [
            INSTANCE_FILE,
            KEY_FILE,
            PUBLIC_FILE,
            ALLOWED_FILE,
            POLICY_FILE,
        ] {
            assert!(dir.join(name).is_file(), "{name} missing");
        }
        let before = fs::read(dir.join(ALLOWED_FILE)).unwrap();
        assert_eq!(run(["init".to_owned()].into_iter()), EXIT_OK);
        assert_eq!(fs::read(dir.join(ALLOWED_FILE)).unwrap(), before);

        let code = run([
            "add".to_owned(),
            "alice@org".to_owned(),
            format!("ssh-ed25519 {KEY}"),
        ]
        .into_iter());
        assert_eq!(code, EXIT_OK);
        assert_eq!(load(&dir).unwrap().signers.len(), 2);
        let bad = run([
            "add".to_owned(),
            "*".to_owned(),
            format!("ssh-ed25519 {KEY}"),
        ]
        .into_iter());
        assert_eq!(bad, EXIT_REFUSED);
    }
}
